/**
 * The AI check of the claims registry: Claude Opus 5.5, prompted to act as a senior
 * GNSS/SBAS integrity engineer, checked each claim against its sources (reading the
 * public ones it could reach) and gave a verdict; a second pass re-checked every
 * correction and every unresolved claim against the primary documents. A claim with an
 * entry here shows as "Checked by AI, awaiting expert" (index.ts). This is not a
 * sign-off: "Reviewed" stays for a named, qualified reviewer. Claims the model could not
 * trace keep their status and are listed in report.ts OPEN_QUESTIONS.
 */
import type { AiCheck } from './types'

const MODEL = 'Claude Opus 5.5'
const ON = '2026-10-05'

/** `on` only when the entry was re-checked after the main pass (its text or value changed). */
type Entry = Omit<AiCheck, 'model' | 'on'> & { on?: string }
type Checked = AiCheck['checked'][number]

/** A document the check read itself. */
const read = (source: string, section?: string): Checked => ({ source, section, read: true })
/** A document the check could not read: the point rests on expertise or on what quotes it. */
const known = (source: string, section?: string): Checked => ({ source, section, read: false })

